const localRepositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const repositoryRoot = process.env.GITHUB_WORKSPACE
  ? realpathSync(process.env.GITHUB_WORKSPACE)
  : localRepositoryRoot;
const implementations = Object.freeze({"dependencies":"#!/usr/bin/env node\n\n// 全仓依赖检查只读取受 Git 管理的 manifest、lockfile、工具链和 workflow；\n// 更新必须由人工明确执行并经过产品真实验收，CI/Release 不得自动改写依赖。\nimport { existsSync, readFileSync } from \"node:fs\";\nimport { spawnSync } from \"node:child_process\";\nimport { dirname, resolve } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\n\nconst repositoryRoot = process.env.GMB_REPOSITORY_ROOT || process.cwd();\nconst contractPath = resolve(repositoryRoot, \".github/dependencies.json\");\nconst contract = JSON.parse(readFileSync(contractPath, \"utf8\"));\nconst [command = \"check\", ...argumentsList] = process.argv.slice(2);\nconst scopeIndex = argumentsList.indexOf(\"--scope\");\nconst scopeName = scopeIndex >= 0 ? argumentsList[scopeIndex + 1] : \"repository\";\nconst shaPattern = /^[0-9a-f]{40}$/;\n\nfunction fail(message) {\n  throw new Error(message);\n}\n\nfunction pathFor(relativePath) {\n  return resolve(repositoryRoot, relativePath);\n}\n\nfunction read(relativePath) {\n  const absolutePath = pathFor(relativePath);\n  if (!existsSync(absolutePath)) {\n    fail(`缺少依赖文件：${relativePath}`);\n  }\n  return readFileSync(absolutePath, \"utf8\");\n}\n\nfunction trackedFiles(patterns) {\n  const result = spawnSync(\"git\", [\"ls-files\", \"--cached\", \"--others\", \"--exclude-standard\", \"--\", ...patterns], {\n    cwd: repositoryRoot,\n    encoding: \"utf8\",\n  });\n  if (result.status !== 0) {\n    fail(`无法读取 Git 文件清单：${result.stderr.trim()}`);\n  }\n  return result.stdout\n    .split(\"\\n\")\n    .filter(Boolean)\n    .filter((relativePath) => existsSync(pathFor(relativePath)));\n}\n\nfunction requireText(relativePath, expected, description) {\n  if (!read(relativePath).includes(expected)) {\n    fail(`${relativePath} 未满足${description}：${expected}`);\n  }\n}\n\n// 中文注释：构建与封装必须按固定顺序出现，避免只命中两个无关字符串却没有形成正式流程。\nfunction requireOrderedText(relativePath, expectedValues, description) {\n  const text = read(relativePath);\n  let offset = -1;\n  for (const expected of expectedValues) {\n    const next = text.indexOf(expected, offset + 1);\n    if (next < 0) fail(`${relativePath} 未满足${description}：${expected}`);\n    offset = next;\n  }\n}\n\nfunction escapeRegex(value) {\n  return value.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n}\n\nfunction exactCargoDependencyVersion(manifest, dependency) {\n  const tableMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\\\\{[^\\\\n}]*\\\\bversion\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const scalarMatch = manifest.match(new RegExp(\n    `^${escapeRegex(dependency)}\\\\s*=\\\\s*\"=([^\"]+)\"`,\n    \"m\",\n  ));\n  const match = tableMatch ?? scalarMatch;\n  if (!match) {\n    fail(`citizenchain/node/Cargo.toml 必须准确固定 ${dependency}`);\n  }\n  return match[1];\n}\n\nfunction cargoLockPackageVersion(lock, packageName) {\n  const match = lock.match(new RegExp(\n    `\\\\[\\\\[package\\\\]\\\\]\\\\r?\\\\nname = \"${escapeRegex(packageName)}\"\\\\r?\\\\nversion = \"([^\"]+)\"`,\n  ));\n  if (!match) {\n    fail(`citizenchain/Cargo.lock 缺少 ${packageName}`);\n  }\n  return match[1];\n}\n\nfunction majorMinor(version, dependency) {\n  const match = version.match(/^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$/);\n  if (!match) {\n    fail(`${dependency} 不是规范三段版本：${version}`);\n  }\n  return `${match[1]}.${match[2]}`;\n}\n\nfunction checkTauri() {\n  const cargoManifest = read(\"citizenchain/node/Cargo.toml\");\n  const cargoLock = read(\"citizenchain/Cargo.lock\");\n  const npmManifest = JSON.parse(read(\"citizenchain/node/frontend/package.json\"));\n  const npmLock = JSON.parse(read(\"citizenchain/node/frontend/package-lock.json\"));\n  const rootPackage = npmLock.packages?.[\"\"];\n  const rustVersions = {\n    tauri: contract.tauri.core.rust,\n    \"tauri-build\": contract.tauri.build,\n    \"tauri-plugin-dialog\": contract.tauri.plugins.dialog,\n    \"tauri-plugin-process\": contract.tauri.plugins.process,\n    \"tauri-plugin-updater\": contract.tauri.plugins.updater,\n  };\n  const npmVersions = {\n    \"@tauri-apps/api\": contract.tauri.core.api,\n    \"@tauri-apps/cli\": contract.tauri.core.cli,\n    \"@tauri-apps/plugin-dialog\": contract.tauri.plugins.dialog,\n    \"@tauri-apps/plugin-process\": contract.tauri.plugins.process,\n    \"@tauri-apps/plugin-updater\": contract.tauri.plugins.updater,\n  };\n\n  for (const [dependency, expected] of Object.entries(rustVersions)) {\n    if (exactCargoDependencyVersion(cargoManifest, dependency) !== expected) {\n      fail(`citizenchain/node/Cargo.toml 的 ${dependency} 必须准确固定为 ${expected}`);\n    }\n    if (cargoLockPackageVersion(cargoLock, dependency) !== expected) {\n      fail(`citizenchain/Cargo.lock 的 ${dependency} 必须锁定为 ${expected}`);\n    }\n  }\n  for (const [dependency, expected] of Object.entries(npmVersions)) {\n    const manifestVersion = npmManifest.dependencies?.[dependency]\n      ?? npmManifest.devDependencies?.[dependency];\n    const rootVersion = rootPackage?.dependencies?.[dependency]\n      ?? rootPackage?.devDependencies?.[dependency];\n    const lockVersion = npmLock.packages?.[`node_modules/${dependency}`]?.version;\n    if (manifestVersion !== expected || rootVersion !== expected || lockVersion !== expected) {\n      fail(`citizenchain/node/frontend 的 ${dependency} 必须在 manifest 与 lockfile 准确固定为 ${expected}`);\n    }\n  }\n  for (const [packagePath, metadata] of Object.entries(npmLock.packages ?? {})) {\n    if (packagePath.startsWith(\"node_modules/@tauri-apps/cli-\")\n      && metadata.version !== contract.tauri.core.cli) {\n      fail(`${packagePath} 必须与 @tauri-apps/cli 同为 ${contract.tauri.core.cli}`);\n    }\n  }\n\n  const coreMinor = majorMinor(contract.tauri.core.rust, \"tauri\");\n  for (const [dependency, version] of [\n    [\"@tauri-apps/api\", contract.tauri.core.api],\n    [\"@tauri-apps/cli\", contract.tauri.core.cli],\n  ]) {\n    if (majorMinor(version, dependency) !== coreMinor) {\n      fail(`Tauri core 主次版本不一致：tauri=${contract.tauri.core.rust} ${dependency}=${version}`);\n    }\n  }\n\n  const cli = \"node frontend/node_modules/@tauri-apps/cli/tauri.js\";\n  for (const workflow of contract.scopes[\"citizenchain-node\"].workflows) {\n    const text = read(workflow);\n    if (text.includes(\"cargo install tauri-cli\") || /\\bcargo tauri\\b/.test(text)) {\n      fail(`${workflow} 仍依赖浮动或全局 Tauri CLI`);\n    }\n    if (!text.includes(`${cli} build --ci -- --locked`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 构建`);\n    }\n    if (workflow.includes(\"-release-\") && !text.includes(`${cli} signer sign`)) {\n      fail(`${workflow} 未使用仓库锁定的 Tauri CLI 签名 updater`);\n    }\n  }\n  for (const script of [\"citizenchain/scripts/run.sh\", \"citizenchain/scripts/clean-run.sh\"]) {\n    if (/\\bcargo tauri\\b/.test(read(script))) {\n      fail(`${script} 仍依赖本机全局 Tauri CLI`);\n    }\n  }\n  const runScript = \"citizenchain/scripts/run.sh\";\n  requireOrderedText(runScript, [\n    `${cli} build --config \"$tauri_override\"`,\n    `--no-bundle --ci -- --locked`,\n    `${cli} bundle --config \"$tauri_override\"`,\n    `--bundles app --ci`,\n  ], \"仓库 Tauri CLI 正式编译与封装顺序\");\n  if (read(runScript).includes(`${cli} build --bundles app --ci`)) {\n    fail(`${runScript} 禁止恢复编译与封装合并的旧 Tauri 命令`);\n  }\n  requireText(\"citizenchain/scripts/clean-run.sh\", `${cli} dev -- --locked`, \"仓库 Tauri CLI 开发构建\");\n}\n\nfunction checkRequiredFiles(scope) {\n  for (const relativePath of scope.requiredFiles) {\n    read(relativePath);\n  }\n}\n\nfunction checkPackageLocks(projects) {\n  for (const directory of projects) {\n    const manifest = JSON.parse(read(`${directory}/package.json`));\n    const lock = JSON.parse(read(`${directory}/package-lock.json`));\n    const rootPackage = lock.packages?.[\"\"];\n    if (lock.lockfileVersion !== 3) {\n      fail(`${directory}/package-lock.json 必须使用 lockfileVersion 3`);\n    }\n    if (!rootPackage || rootPackage.name !== manifest.name) {\n      fail(`${directory} 的 package.json 与 package-lock.json 包名不一致`);\n    }\n    if (manifest.version && rootPackage.version !== manifest.version) {\n      fail(`${directory} 的 package.json 与 package-lock.json 版本不一致`);\n    }\n  }\n}\n\nfunction dartScalar(relativePath, dependency) {\n  const escaped = dependency.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const match = read(relativePath).match(new RegExp(`^  ${escaped}:\\\\s*([^#\\\\n]+?)\\\\s*$`, \"m\"));\n  if (!match) {\n    fail(`${relativePath} 缺少统一 Dart 依赖：${dependency}`);\n  }\n  return match[1].trim();\n}\n\nfunction checkSharedDartDependencies() {\n  for (const dependency of contract.sharedDartDependencies) {\n    const appVersion = dartScalar(\"citizenapp/pubspec.yaml\", dependency);\n    const walletVersion = dartScalar(\"citizenwallet/pubspec.yaml\", dependency);\n    if (appVersion !== walletVersion) {\n      fail(`移动端共享依赖 ${dependency} 版本不一致：CitizenApp=${appVersion} CitizenWallet=${walletVersion}`);\n    }\n  }\n}\n\nfunction checkToolchains(name) {\n  const { node, rust, flutter, java, gradle, androidNdk } = contract.toolchains;\n  const mobileScope = name === \"repository\" || [\"citizenapp\", \"citizensdk\", \"citizenwallet\"].includes(name);\n  const chainScope = name === \"repository\" || [\"citizenchain-node\", \"citizenchain-runtime\"].includes(name);\n  const nodeScope = name === \"repository\" || [\"citizenchain-node\", \"citizensdk\", \"citizenserve\", \"citizenweb\"].includes(name);\n  if (mobileScope) {\n    majorMinor(flutter, \"Flutter\");\n  }\n  if (!/^\\d+(?:\\.\\d+){2}$/.test(androidNdk)) {\n    fail(`Android NDK 版本无效：${androidNdk}`);\n  }\n  const rustFiles = name === \"repository\"\n    ? [\"citizenchain/rust-toolchain.toml\", \"citizenapp/smoldot/ffi/rust-toolchain.toml\", \"citizensdk/native/smoldot/ffi/rust-toolchain.toml\"]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/smoldot/ffi/rust-toolchain.toml\"]\n      : name === \"citizensdk\"\n        ? [\"citizensdk/native/smoldot/ffi/rust-toolchain.toml\"]\n        : chainScope\n        ? [\"citizenchain/rust-toolchain.toml\"]\n        : [];\n  for (const file of rustFiles) {\n    requireText(file, `channel = \"${rust}\"`, \"Rust 版本统一契约\");\n  }\n  const nodeFiles = name === \"repository\"\n    ? [\"citizenchain/node/frontend/.nvmrc\", \"citizenweb/.nvmrc\"]\n    : name === \"citizenchain-node\"\n      ? [\"citizenchain/node/frontend/.nvmrc\"]\n      : name === \"citizenweb\"\n        ? [\"citizenweb/.nvmrc\"]\n        : [];\n  for (const file of nodeFiles) {\n    if (read(file).trim() !== node) {\n      fail(`${file} 必须精确固定 Node.js ${node}`);\n    }\n  }\n  const gradleFiles = name === \"repository\"\n    ? [\n        \"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\",\n        \"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\",\n      ]\n    : name === \"citizenapp\"\n      ? [\"citizenapp/android/gradle/wrapper/gradle-wrapper.properties\"]\n      : name === \"citizenwallet\"\n        ? [\"citizenwallet/android/gradle/wrapper/gradle-wrapper.properties\"]\n        : [];\n  for (const file of gradleFiles) {\n    requireText(file, `gradle-${gradle}-all.zip`, \"Gradle 版本统一契约\");\n  }\n  const workflows = name === \"repository\"\n    ? trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ])\n    : contract.scopes[name].workflows;\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/node-version:\\s*(?:['\"])?25(?:['\"])?\\s*$/m.test(text)) {\n      fail(`${workflow} 仍使用浮动 Node.js 25，必须精确固定 ${node}`);\n    }\n    if (nodeScope && text.includes(\"node-version:\") && !text.includes(`node-version: ${node}`)) {\n      fail(`${workflow} 的 Node.js 版本未统一为 ${node}`);\n    }\n    if (text.includes(\"java-version:\") && !text.includes(`java-version: ${java}`)) {\n      fail(`${workflow} 的 Java 版本未统一为 ${java}`);\n    }\n    if (workflow.includes(\"/citizensdk/\") && !text.includes(`ndk;${androidNdk}`)) {\n      fail(`${workflow} 的 Android NDK 版本未统一为 ${androidNdk}`);\n    }\n  }\n}\n\nfunction checkActions(workflows) {\n  for (const [action, sha] of Object.entries(contract.actions)) {\n    if (!shaPattern.test(sha)) {\n      fail(`${action} 未配置完整 commit SHA`);\n    }\n  }\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    for (const match of text.matchAll(/^\\s*uses:\\s*([^\\s#]+)(?:\\s+#.*)?$/gm)) {\n      const reference = match[1];\n      if (reference.startsWith(\"./\") || reference.startsWith(\"docker://\")) {\n        continue;\n      }\n      const separator = reference.lastIndexOf(\"@\");\n      const action = reference.slice(0, separator);\n      const revision = reference.slice(separator + 1);\n      if (!contract.actions[action]) {\n        fail(`${workflow} 使用了未登记 Action：${action}`);\n      }\n      if (revision !== contract.actions[action]) {\n        fail(`${workflow} 的 ${action} 未固定到统一 SHA ${contract.actions[action]}`);\n      }\n    }\n  }\n}\n\nfunction checkOfficialRunners(workflows) {\n  const allowed = new Set(contract.officialRunners);\n  for (const workflow of workflows) {\n    const text = read(workflow);\n    if (/runs-on:\\s*(?:\\[[^\\]]*\\bself-hosted\\b|\\bself-hosted\\b)/m.test(text)) {\n      fail(`${workflow} 使用了 self-hosted runner，必须使用统一官方镜像`);\n    }\n    const runnerLabels = [\n      ...text.matchAll(/^\\s*runs-on:\\s*((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)\\s*$/gm),\n      ...text.matchAll(/[\"']os[\"']\\s*:\\s*[\"']((?:ubuntu|macos|windows)-[a-zA-Z0-9.-]+)[\"']/g),\n    ];\n    for (const match of runnerLabels) {\n      if (!allowed.has(match[1])) {\n        fail(`${workflow} 使用了未登记的 runner 镜像：${match[1]}`);\n      }\n    }\n  }\n}\n\nfunction checkGitDependencies(manifests) {\n  for (const manifest of manifests) {\n    const text = read(manifest);\n    if (/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\b(branch|tag)\\s*=/m.test(text)) {\n      fail(`${manifest} 存在可漂移的 Git branch/tag 依赖，必须使用 rev`);\n    }\n    for (const match of text.matchAll(/git\\s*=\\s*\"[^\"]+\"[^\\n}]*\\brev\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!shaPattern.test(match[1])) {\n        fail(`${manifest} 的 Git rev 不是完整 commit SHA：${match[1]}`);\n      }\n    }\n  }\n}\n\n// 中文注释：本地路径依赖必须从声明它的 manifest 目录解析；仅检查文件存在会漏掉\n// Cargo workspace 解析错误，因此全仓还会逐个执行 cargo metadata。\nfunction checkLocalDependencyPaths() {\n  const cargoManifests = trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]);\n  for (const manifest of cargoManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/\\bpath\\s*=\\s*\"([^\"]+)\"/g)) {\n      if (!existsSync(resolve(manifestDirectory, match[1]))) {\n        fail(`${manifest} 的 Cargo 本地依赖不存在：${match[1]}`);\n      }\n    }\n  }\n\n  const dartManifests = trackedFiles([\"**/pubspec.yaml\", \"pubspec.yaml\"]);\n  for (const manifest of dartManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    for (const match of read(manifest).matchAll(/^ {4}path:\\s*([^#\\n]+?)\\s*$/gm)) {\n      const dependencyPath = match[1].trim().replace(/^['\"]|['\"]$/g, \"\");\n      if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n        fail(`${manifest} 的 Dart 本地依赖不存在：${dependencyPath}`);\n      }\n    }\n  }\n\n  const npmManifests = trackedFiles([\"**/package.json\", \"package.json\"])\n    .filter((manifest) => !manifest.includes(\"/dist/\"));\n  for (const manifest of npmManifests) {\n    const manifestDirectory = dirname(pathFor(manifest));\n    const packageManifest = JSON.parse(read(manifest));\n    for (const dependencies of [\n      packageManifest.dependencies,\n      packageManifest.devDependencies,\n      packageManifest.optionalDependencies,\n    ]) {\n      for (const [dependency, version] of Object.entries(dependencies ?? {})) {\n        if (typeof version !== \"string\" || !version.startsWith(\"file:\")) continue;\n        const dependencyPath = version.slice(\"file:\".length);\n        if (!existsSync(resolve(manifestDirectory, dependencyPath))) {\n          fail(`${manifest} 的 npm 本地依赖 ${dependency} 不存在：${dependencyPath}`);\n        }\n      }\n    }\n  }\n}\n\nfunction checkCargoMetadata() {\n  for (const directory of contract.cargoProjects) {\n    console.log(`\\n[${directory}] cargo metadata --format-version 1 --locked --no-deps`);\n    const result = spawnSync(\n      \"cargo\",\n      [\"metadata\", \"--format-version\", \"1\", \"--locked\", \"--no-deps\"],\n      { cwd: pathFor(directory), encoding: \"utf8\" },\n    );\n    if (result.error) fail(`无法执行 cargo metadata：${result.error.message}`);\n    if (result.status !== 0) {\n      const detail = (result.stderr || result.stdout || \"\").trim();\n      fail(`${directory} 的 Cargo workspace 无法解析：${detail}`);\n    }\n  }\n}\n\nfunction workflowActionScript(workflow) {\n  if (workflow === '.github/workflows/gmb-repository.yml') {\n    return '.github/scripts/gmb-repository/ci-repository.mjs';\n  }\n  return workflow.replace(/^\\.github\\/workflows\\//, '.github/scripts/').replace(/\\.ya?ml$/, '.mjs');\n}\n\nfunction checkWorkflowScopes() {\n  const productWorkflows = [];\n  const expectedWorkflows = [];\n  const legacyName = `${\"gmb-ci\"}-repository.yml`;\n  for (const [name, scope] of Object.entries(contract.scopes)) {\n    for (const workflow of scope.workflows) {\n      expectedWorkflows.push(workflow);\n      const text = read(workflow);\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      if (!text.includes(invocation)) {\n        fail(`${workflow} 未调用依赖作用域：${name}`);\n      }\n      if (name !== \"repository\") {\n        productWorkflows.push(workflow);\n        if (text.includes(\"gmb-repository.yml\") || text.includes(legacyName)) {\n          fail(`${workflow} 不得调用或依赖仓库门禁`);\n        }\n      }\n    }\n  }\n  if (productWorkflows.length !== 24) {\n    fail(`产品 CI/Release workflow 必须精确为 24 条，当前契约登记 ${productWorkflows.length} 条`);\n  }\n  const actualWorkflows = trackedFiles([\n    \".github/workflows/*.yml\",\n    \".github/workflows/*.yaml\",\n    \".github/workflows/*/*.yml\",\n    \".github/workflows/*/*.yaml\",\n  ]);\n  const expected = [...expectedWorkflows].sort();\n  const actual = [...actualWorkflows].sort();\n  if (JSON.stringify(actual) !== JSON.stringify(expected)) {\n    fail(`workflow 清单与依赖契约不一致：期望 ${expected.length} 条，实际 ${actual.length} 条`);\n  }\n  const legacyWorkflow = `.github/workflows/${\"gmb-ci\"}-repository.yml`;\n  if (existsSync(pathFor(legacyWorkflow))) {\n    fail(`旧仓库门禁 ${legacyWorkflow} 仍存在`);\n  }\n}\n\nfunction checkFrozenCommands(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    for (const workflow of scope.workflows) {\n      const text = read(workflow);\n      if ([\"citizenapp\", \"citizensdk\", \"citizenwallet\"].includes(name) && !text.includes(\"flutter pub get --enforce-lockfile\")) {\n        fail(`${workflow} 未冻结 Flutter/Dart 应用依赖`);\n      }\n      if ([\"citizenserve\", \"citizenweb\"].includes(name) && !text.includes(\"npm ci\")) {\n        fail(`${workflow} 未使用 npm ci`);\n      }\n      if ([\"citizenchain-node\", \"citizenchain-runtime\", \"citizensdk\"].includes(name) && !text.includes(\"--locked\")) {\n        fail(`${workflow} 未冻结 Cargo 依赖`);\n      }\n    }\n  }\n}\n\nfunction checkAuditGates(scopeNames) {\n  for (const name of scopeNames) {\n    const scope = contract.scopes[name];\n    const audited = contract.auditedScopes.includes(name);\n    const hasCargo = contract.cargoProjects.some((directory) =>\n      scope.requiredFiles.includes(projectFile(directory, \"Cargo.toml\")));\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies audit --scope ${name}`;\n      const text = read(workflow);\n      if (audited && !text.includes(invocation)) {\n        fail(`${workflow} 未接入已清零产品的阻断安全审计：${name}`);\n      }\n      if (!audited && text.includes(invocation)) {\n        fail(`${workflow} 接入了尚未登记零漏洞基线的安全审计：${name}`);\n      }\n      if (audited && hasCargo && !text.includes(\n        `cargo install cargo-audit --version ${contract.toolchains.cargoAudit} --locked`,\n      )) {\n        fail(`${workflow} 未安装固定版本 cargo-audit ${contract.toolchains.cargoAudit}`);\n      }\n    }\n  }\n}\n\nfunction checkScope(name) {\n  const scope = contract.scopes[name];\n  if (!scope) {\n    fail(`未知依赖作用域：${name}`);\n  }\n  checkRequiredFiles(scope);\n  if (name === \"repository\" || name === \"citizenchain-node\") {\n    checkTauri();\n  }\n  if (name === \"repository\") {\n    for (const candidate of Object.values(contract.scopes)) {\n      checkRequiredFiles(candidate);\n    }\n    checkPackageLocks(contract.npmProjects);\n    for (const directory of contract.dartApplications) {\n      read(`${directory}/pubspec.yaml`);\n      read(`${directory}/pubspec.lock`);\n    }\n    for (const directory of contract.cargoProjects) {\n      read(`${directory}/Cargo.toml`);\n      read(`${directory}/Cargo.lock`);\n    }\n    checkSharedDartDependencies();\n    checkToolchains(name);\n    const workflows = trackedFiles([\n      \".github/workflows/*.yml\",\n      \".github/workflows/*.yaml\",\n      \".github/workflows/*/*.yml\",\n      \".github/workflows/*/*.yaml\",\n    ]);\n    checkActions(workflows);\n    checkOfficialRunners(workflows);\n    checkGitDependencies(trackedFiles([\"**/Cargo.toml\", \"Cargo.toml\"]));\n    checkLocalDependencyPaths();\n    checkCargoMetadata();\n    checkWorkflowScopes();\n    checkFrozenCommands(Object.keys(contract.scopes));\n    checkAuditGates(Object.keys(contract.scopes));\n  } else {\n    checkPackageLocks(contract.npmProjects.filter((directory) =>\n      scope.requiredFiles.includes(`${directory}/package.json`)));\n    checkToolchains(name);\n    checkActions(scope.workflows);\n    checkOfficialRunners(scope.workflows);\n    checkGitDependencies(scope.requiredFiles.filter((file) => file.endsWith(\"Cargo.toml\")));\n    checkFrozenCommands([name]);\n    checkAuditGates([name]);\n    for (const workflow of scope.workflows) {\n      const invocation = `node ${workflowActionScript(workflow)} dependencies check --scope ${name}`;\n      requireText(workflow, invocation, \"产品依赖作用域检查\");\n    }\n  }\n  console.log(`依赖检查通过：${name}`);\n}\n\nfunction projectFile(directory, fileName) {\n  return directory === \".\" ? fileName : `${directory}/${fileName}`;\n}\n\nfunction scopedProjects(projects, fileName) {\n  if (scopeName === \"repository\") {\n    return projects;\n  }\n  const requiredFiles = contract.scopes[scopeName]?.requiredFiles;\n  if (!requiredFiles) {\n    fail(`未知依赖作用域：${scopeName}`);\n  }\n  return projects.filter((directory) => requiredFiles.includes(projectFile(directory, fileName)));\n}\n\nfunction runNative(executable, argumentsValue, cwd, allowFailure = false) {\n  console.log(`\\n[${cwd}] ${executable} ${argumentsValue.join(\" \")}`);\n  const result = spawnSync(executable, argumentsValue, {\n    cwd: pathFor(cwd),\n    encoding: \"utf8\",\n    stdio: \"inherit\",\n  });\n  if (result.error) {\n    fail(`无法执行 ${executable}：${result.error.message}`);\n  }\n  if (result.status !== 0 && !allowFailure) {\n    fail(`${executable} 检查失败，退出码 ${result.status}`);\n  }\n}\n\nfunction audit() {\n  checkScope(scopeName);\n  const npmProjects = scopedProjects(contract.npmProjects, \"package.json\");\n  const cargoProjects = scopedProjects(contract.cargoProjects, \"Cargo.toml\");\n  for (const directory of npmProjects) {\n    runNative(\"npm\", [\"audit\", \"--audit-level=low\"], directory);\n  }\n  if (cargoProjects.length > 0) {\n    const auditVersion = spawnSync(\"cargo\", [\"audit\", \"--version\"], { encoding: \"utf8\" });\n    if (auditVersion.status !== 0 || !auditVersion.stdout.includes(contract.toolchains.cargoAudit)) {\n      fail(`cargo-audit 必须安装并固定为 ${contract.toolchains.cargoAudit}`);\n    }\n    for (const [index, directory] of cargoProjects.entries()) {\n      const argumentsValue = [\"audit\"];\n      if (index > 0) {\n        argumentsValue.push(\"--no-fetch\");\n      }\n      argumentsValue.push(\"--file\", projectFile(directory, \"Cargo.lock\"));\n      runNative(\"cargo\", argumentsValue, \".\");\n    }\n  }\n}\n\nfunction outdated() {\n  checkScope(scopeName);\n  for (const directory of scopedProjects(contract.npmProjects, \"package.json\")) {\n    runNative(\"npm\", [\"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.dartApplications, \"pubspec.yaml\")) {\n    runNative(\"dart\", [\"pub\", \"outdated\"], directory, true);\n  }\n  for (const directory of scopedProjects(contract.cargoProjects, \"Cargo.toml\")) {\n    runNative(\"cargo\", [\"update\", \"--dry-run\", \"--manifest-path\", projectFile(directory, \"Cargo.toml\")], \".\", true);\n  }\n  console.log(\"\\n过期版本仅报告；更新 manifest/lockfile 后必须重新执行产品真实验收。\");\n}\n\ntry {\n  if (contract.schema !== 1) {\n    fail(`不支持依赖契约 schema：${contract.schema}`);\n  }\n  if (command === \"check\") {\n    checkScope(scopeName);\n  } else if (command === \"audit\") {\n    audit();\n  } else if (command === \"outdated\") {\n    outdated();\n  } else {\n    fail(`未知命令：${command}`);\n  }\n} catch (error) {\n  console.error(`依赖检查失败：${error.message}`);\n  process.exitCode = 1;\n}\n","version-tag":"#!/usr/bin/env node\n\nimport { execFileSync } from 'node:child_process';\nimport { readFileSync } from 'node:fs';\nimport { pathToFileURL } from 'node:url';\n\nconst semanticVersionPattern = /^(0|[1-9]\\d*)\\.(0|[1-9]\\d?)\\.(0|[1-9]\\d?)$/;\nconst tagPrefixPattern = /^[a-z0-9][a-z0-9-]*-v$/;\nconst sourceSHAPattern = /^[0-9a-f]{40}$/;\nconst workflowFilePattern = /^(?:[a-z0-9-]+\\/)*[a-z0-9-]+\\.ya?ml$/;\n\nexport function validateWorkflowFileName(value) {\n  if (!workflowFilePattern.test(String(value))) throw new Error('workflow 无效');\n  return value;\n}\n\nexport function parseSemanticVersion(value) {\n  const match = semanticVersionPattern.exec(String(value));\n  if (!match) throw new Error(`软件版本必须形如 a.b.c 且 b、c 不超过 99：${value}`);\n  return match.slice(1).map(Number);\n}\n\nexport function compareSemanticVersions(left, right) {\n  const a = parseSemanticVersion(left);\n  const b = parseSemanticVersion(right);\n  for (let index = 0; index < 3; index += 1) {\n    if (a[index] !== b[index]) return a[index] - b[index];\n  }\n  return 0;\n}\n\nexport function nextSemanticVersion(value) {\n  let [major, minor, patch] = parseSemanticVersion(value);\n  patch += 1;\n  if (patch > 99) {\n    patch = 0;\n    minor += 1;\n  }\n  if (minor > 99) {\n    minor = 0;\n    major += 1;\n  }\n  return `${major}.${minor}.${patch}`;\n}\n\nexport function expectedSemanticCandidate(seed, successfulVersions) {\n  parseSemanticVersion(seed);\n  const normalized = [...new Set(successfulVersions.map((value) => {\n    parseSemanticVersion(value);\n    return value;\n  }))].sort(compareSemanticVersions);\n  return normalized.length === 0 ? seed : nextSemanticVersion(normalized.at(-1));\n}\n\nfunction parseArguments(argv) {\n  const [command, ...rest] = argv;\n  if (!command) throw new Error('缺少版本命令');\n  const values = {};\n  for (let index = 0; index < rest.length; index += 2) {\n    const key = rest[index];\n    const value = rest[index + 1];\n    if (!key?.startsWith('--') || value === undefined) throw new Error(`参数格式无效：${key ?? ''}`);\n    const name = key.slice(2);\n    if (Object.hasOwn(values, name)) throw new Error(`参数重复：${key}`);\n    values[name] = value;\n  }\n  return { command, values };\n}\n\nfunction requireExactKeys(values, required, optional = []) {\n  const allowed = new Set([...required, ...optional]);\n  for (const key of Object.keys(values)) {\n    if (!allowed.has(key)) throw new Error(`不支持的参数：--${key}`);\n  }\n  for (const key of required) {\n    if (!Object.hasOwn(values, key) || values[key] === '') throw new Error(`缺少参数：--${key}`);\n  }\n}\n\nfunction ghJSON(path) {\n  const output = execFileSync('gh', ['api', path], {\n    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],\n  });\n  try {\n    return JSON.parse(output);\n  } catch {\n    throw new Error(`GitHub API 返回了无效 JSON：${path}`);\n  }\n}\n\nfunction readSeed(kind, path) {\n  const text = readFileSync(path, 'utf8');\n  if (kind === 'json') {\n    const value = JSON.parse(text)?.version;\n    parseSemanticVersion(value);\n    return value;\n  }\n  if (kind === 'pubspec') {\n    const matches = [...text.matchAll(/^version:\\s*([^+\\s]+)(?:\\+\\d+)?\\s*$/gm)];\n    if (matches.length !== 1) throw new Error(`pubspec 软件版本真源不唯一：${path}`);\n    parseSemanticVersion(matches[0][1]);\n    return matches[0][1];\n  }\n  throw new Error(`不支持的版本真源类型：${kind}`);\n}\n\nfunction publishedSemanticVersions(prefix) {\n  if (!tagPrefixPattern.test(prefix)) throw new Error('Tag 前缀无效');\n  const escaped = prefix.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n  const pattern = new RegExp(`^${escaped}(${semanticVersionPattern.source.slice(1, -1)})$`);\n  const versions = [];\n  for (let page = 1; page <= 100; page += 1) {\n    const releases = ghJSON(`repos/{owner}/{repo}/releases?per_page=100&page=${page}`);\n    if (!Array.isArray(releases)) throw new Error('GitHub Release 列表格式无效');\n    for (const release of releases) {\n      if (release?.draft === true || release?.prerelease === true) continue;\n      const tag = String(release?.tag_name || '');\n      if (!tag.startsWith(prefix)) continue;\n      const match = pattern.exec(tag);\n      if (!match) throw new Error(`同前缀正式 Release Tag 不符合统一版本契约：${tag}`);\n      parseSemanticVersion(match[1]);\n      versions.push(match[1]);\n    }\n    if (releases.length < 100) return versions;\n  }\n  throw new Error('GitHub Release 列表超过安全分页上限');\n}\n\nfunction validateIdentity(values) {\n  if (!/^[a-z][a-z0-9-]*$/.test(values['product-id'])) throw new Error('product_id 无效');\n  if (!/^[a-z][a-z0-9-]*$/.test(values.target)) throw new Error('target 无效');\n  validateWorkflowFileName(values.workflow);\n  if (!sourceSHAPattern.test(values['source-sha'])) throw new Error('source_sha 无效');\n  if (!/^[1-9]\\d*$/.test(values['ci-run-id'])) throw new Error('ci_run_id 无效');\n}\n\nfunction verifySuccessfulCIRun(values) {\n  validateIdentity(values);\n  const ciTitles = {\n    'citizenapp/ci-ios.yml': '公民 · CI · iOS',\n    'citizenapp/ci-android.yml': '公民 · CI · Android',\n    'citizenwallet/ci-ios.yml': '公民钱包 · CI · iOS',\n    'citizenwallet/ci-android.yml': '公民钱包 · CI · Android',\n    'citizensdk/ci-sdk.yml': '公民SDK · CI · SDK',\n    'citizenserve/ci-cloudflare.yml': '公民服务端 · CI · Cloudflare',\n    'citizenweb/ci-web.yml': '公民网 · CI · Web',\n    'citizenchain/ci-runtime-wasm.yml': '公民协议 · CI · WASM',\n    'citizenchain/ci-node-linux-arm.yaml': '公民链 · CI · LinuxARM',\n    'citizenchain/ci-node-linux-amd.yml': '公民链 · CI · LinuxAMD',\n    'citizenchain/ci-node-macos.yml': '公民链 · CI · macOS',\n    'citizenchain/ci-node-windows.yml': '公民链 · CI · Windows',\n  };\n  const expectedTitle = ciTitles[values.workflow];\n  if (!expectedTitle) throw new Error('未登记的 CI workflow');\n  const run = ghJSON(`repos/{owner}/{repo}/actions/runs/${values['ci-run-id']}`);\n  if (run.status !== 'completed' || run.conclusion !== 'success'\n    || run.event !== 'workflow_dispatch' || run.head_branch !== 'main'\n    || run.head_sha !== values['source-sha']\n    || run.display_title !== expectedTitle\n    || !String(run.path || '').endsWith('/gmb-repository.yml')) {\n    throw new Error('Release 来源不是同产品、同端、同 workflow 的成功 CI');\n  }\n  const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();\n  if (head !== values['source-sha']) throw new Error(`checkout 与 source_sha 不一致：${head}`);\n}\n\n// Runtime 正式版本只由 Release 确定；CI 仅证明同一源码已通过验证，因此这里校验\n// Release 的 spec_version 与正式 Tag 一致，不再从 CI 诊断产物读取版本候选。\nfunction verifyRuntimeVersion(values) {\n  const specVersion = Number(values['spec-version']);\n  if (!/^[1-9]\\d*$/.test(values['spec-version'])\n    || !Number.isSafeInteger(specVersion) || specVersion > 2 ** 32 - 1) {\n    throw new Error('spec_version 无效');\n  }\n}\n\nfunction printNextSemanticRelease(values) {\n  requireExactKeys(values, ['prefix', 'seed']);\n  const candidate = expectedSemanticCandidate(\n    values.seed,\n    publishedSemanticVersions(values.prefix),\n  );\n  process.stdout.write(`${candidate}\\n`);\n}\n\nfunction verifyReleaseSource(values) {\n  requireExactKeys(values, [\n    'version-tag', 'source-sha', 'ci-run-id', 'prefix', 'product-id', 'target', 'workflow',\n  ], ['spec-version', 'software-version']);\n  if (!tagPrefixPattern.test(values.prefix)\n    || !values['version-tag'].startsWith(values.prefix)\n    || !/^[a-z0-9][a-z0-9.-]*$/.test(values['version-tag'])) {\n    throw new Error('Release 版本 Tag 身份无效');\n  }\n  verifySuccessfulCIRun(values);\n  const suffix = values['version-tag'].slice(values.prefix.length);\n  if (Object.hasOwn(values, 'spec-version')) {\n    if (values['product-id'] !== 'citizenchain-runtime'\n      || suffix !== values['spec-version']) throw new Error('Runtime Release 版本参数无效');\n    verifyRuntimeVersion(values);\n  } else {\n    const seedSources = {\n      citizenapp: ['pubspec', 'citizenapp/pubspec.yaml'],\n      citizenwallet: ['pubspec', 'citizenwallet/pubspec.yaml'],\n      citizensdk: ['pubspec', 'citizensdk/pubspec.yaml'],\n      'citizenchain-node': ['json', 'citizenchain/node/tauri.conf.json'],\n      citizenserve: ['json', 'citizenserve/package.json'],\n      citizenweb: ['json', 'citizenweb/package.json'],\n    };\n    const source = seedSources[values['product-id']];\n    if (!source) throw new Error('语义版本 Release 缺少版本真源');\n    parseSemanticVersion(suffix);\n    if (values['product-id'] === 'citizensdk') {\n      if (!Object.hasOwn(values, 'software-version')\n        || values['software-version'] !== suffix) {\n        throw new Error('CitizenSDK Tag 与正式软件版本不一致');\n      }\n    } else if (Object.hasOwn(values, 'software-version')) {\n      throw new Error('非 CitizenSDK Release 禁止 software_version 参数');\n    }\n    const expected = expectedSemanticCandidate(\n      readSeed(source[0], source[1]),\n      publishedSemanticVersions(values.prefix),\n    );\n    if (suffix !== expected) {\n      throw new Error(`Release 版本不是正式 Release 真源的下一版本：期望 ${expected}，收到 ${suffix}`);\n    }\n  }\n  process.stdout.write(`Release 已锁定成功 CI：${values['ci-run-id']} · ${values['source-sha']}\\n`);\n}\n\nexport function main(argv) {\n  const { command, values } = parseArguments(argv);\n  if (command === 'next-semantic-release') return printNextSemanticRelease(values);\n  if (command === 'verify-release-source') return verifyReleaseSource(values);\n  throw new Error(`不支持的版本命令：${command}`);\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {\n  try {\n    main(process.argv.slice(2));\n  } catch (error) {\n    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\\n`);\n    process.exitCode = 1;\n  }\n}\n","github-release":"#!/usr/bin/env node\n\nimport { lstatSync, readFileSync } from 'node:fs';\nimport { basename } from 'node:path';\nimport { spawnSync } from 'node:child_process';\nimport { pathToFileURL } from 'node:url';\n\nconst SHA_PATTERN = /^[0-9a-f]{40}$/;\nconst REPOSITORY_PATTERN = /^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/;\nconst TAG_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,199}$/;\nconst READ_ATTEMPTS = 7;\nconst READ_RETRY_MS = 10_000;\n\nfunction required(condition, message) {\n  if (!condition) throw new Error(message);\n}\n\nfunction includedResponseStatus(output) {\n  const pattern = /(?:^|\\r?\\n)HTTP\\/[0-9.]+\\s+([0-9]{3})(?=[ \\t]|\\r?$)/gm;\n  let status = null;\n  for (const match of String(output || '').matchAll(pattern)) status = Number(match[1]);\n  return status;\n}\n\nfunction includedResponseBody(output) {\n  const value = String(output || '');\n  const windowsSeparator = value.lastIndexOf('\\r\\n\\r\\n');\n  if (windowsSeparator >= 0) return value.slice(windowsSeparator + 4);\n  const unixSeparator = value.lastIndexOf('\\n\\n');\n  return unixSeparator >= 0 ? value.slice(unixSeparator + 2) : '';\n}\n\nexport function gh(args, options = {}) {\n  const run = options.run || spawnSync;\n  const wait = options.wait || ((milliseconds) => {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, milliseconds);\n  });\n  const attempts = options.retryRead ? READ_ATTEMPTS : 1;\n  for (let attempt = 1; attempt <= attempts; attempt += 1) {\n    const commandArgs = options.notFound\n      ? [...args, '--include']\n      : args;\n    if (options.notFound) {\n      required(args[0] === 'api' && !args.includes('--include'),\n        'notFound 只允许用于未带 --include 的 GitHub API 读取');\n    }\n    const result = run('gh', commandArgs, {\n      encoding: 'utf8',\n      input: options.input,\n      env: process.env,\n      maxBuffer: 16 * 1024 * 1024,\n    });\n    if (result.error) throw result.error;\n    const stdout = String(result.stdout || '');\n    const stderr = String(result.stderr || '');\n    const response = [stdout, stderr].filter(Boolean).join('\\n');\n    const responseStatus = options.notFound ? includedResponseStatus(response) : null;\n    if (result.status === 0) {\n      if (!options.notFound) return stdout.trim();\n      required(responseStatus !== null, 'GitHub API 读取缺少可核验 HTTP 状态');\n      required(responseStatus >= 200 && responseStatus < 300,\n        `GitHub API 成功进程返回了异常 HTTP 状态：${responseStatus}`);\n      return includedResponseBody(stdout).trim();\n    }\n    const detail = (stderr || stdout).trim();\n    if (options.notFound && responseStatus === 404) return null;\n    // 中文注释：只读查询可以安全重试；创建、上传、发布与删除均可能已经产生副作用，\n    // 禁止用重试掩盖权限或事务错误，必须由下方状态核对与精确回滚收口。\n    const integrationDenied = /HTTP 403:\\s*Resource not accessible by integration/i.test(detail);\n    const retryable = options.retryRead && (integrationDenied || /HTTP 5\\d\\d/i.test(detail));\n    if (!retryable || attempt === attempts) {\n      throw new Error(detail || `gh 执行失败，退出码 ${result.status}`);\n    }\n    console.error(`[GitHub] Release 只读接口暂时不可用，${READ_RETRY_MS / 1000} 秒后重试（${attempt}/${attempts - 1}）`);\n    wait(READ_RETRY_MS);\n  }\n  throw new Error('GitHub Release 只读接口重试状态异常');\n}\n\nfunction json(output, context) {\n  try {\n    return JSON.parse(output);\n  } catch {\n    throw new Error(`${context}返回了无效 JSON`);\n  }\n}\n\nfunction sourceMarker(input) {\n  return `<!-- GMB_RELEASE_SOURCE_SHA:${input.sourceSHA} -->`;\n}\n\nfunction releaseBody(input) {\n  const notes = input.notes ?? readFileSync(input.notesFile, 'utf8');\n  return `${notes.trimEnd()}\\n\\n${sourceMarker(input)}\\n`;\n}\n\nexport function createClient() {\n  return {\n    async listReleases(repository) {\n      const releases = [];\n      for (let page = 1; page <= 100; page += 1) {\n        const output = gh(['api', `repos/${repository}/releases?per_page=100&page=${page}`], {\n          retryRead: true,\n        });\n        const values = json(output, 'GitHub Release 列表');\n        required(Array.isArray(values), 'GitHub Release 列表格式无效');\n        releases.push(...values);\n        if (values.length < 100) return releases;\n      }\n      throw new Error('GitHub Release 列表超过安全分页上限');\n    },\n    async getTag(repository, tag) {\n      const output = gh(['api', `repos/${repository}/git/ref/tags/${encodeURIComponent(tag)}`], {\n        notFound: true,\n        retryRead: true,\n      });\n      return output === null ? null : json(output, 'GitHub Tag');\n    },\n    async getTagObject(repository, objectSHA) {\n      return json(gh(['api', `repos/${repository}/git/tags/${objectSHA}`], { retryRead: true }), 'GitHub Tag 对象');\n    },\n    async createDraft(input) {\n      const args = [\n        'release', 'create', input.tag, '--repo', input.repository,\n        '--target', input.sourceSHA,\n        '--draft', '--title', input.title, '--notes', releaseBody(input),\n        ...input.assets.map((asset) => asset.path),\n      ];\n      // 中文注释：禁止预建或复用旧 Tag。GitHub 在同一个创建请求中通过 --target\n      // 将版本 Tag 原子锚定到本次成功 CI 的 sourceSHA；默认分支后续移动不影响该锚点。\n      gh(args);\n    },\n    async getRelease(repository, releaseId) {\n      const output = gh(['api', `repos/${repository}/releases/${releaseId}`], {\n        notFound: true,\n        retryRead: true,\n      });\n      return output === null ? null : json(output, 'GitHub Release');\n    },\n    async getReleaseByTag(repository, tag) {\n      const output = gh(\n        ['api', `repos/${repository}/releases/tags/${encodeURIComponent(tag)}`],\n        { notFound: true, retryRead: true },\n      );\n      return output === null ? null : json(output, 'GitHub Tag Release');\n    },\n    async publish(repository, releaseId, latest) {\n      const payload = JSON.stringify({ draft: false, make_latest: latest ? 'true' : 'false' });\n      gh(['api', '--method', 'PATCH', `repos/${repository}/releases/${releaseId}`, '--input', '-'], {\n        input: payload,\n      });\n    },\n    async deleteRelease(repository, releaseId) {\n      gh(['api', '--method', 'DELETE', `repos/${repository}/releases/${releaseId}`]);\n    },\n    async deleteTag(repository, tag) {\n      gh(['api', '--method', 'DELETE', `repos/${repository}/git/refs/tags/${encodeURIComponent(tag)}`]);\n    },\n    async wait() {\n      await new Promise((resolve) => setTimeout(resolve, 1_000));\n    },\n  };\n}\n\nfunction verifyAssets(release, assets) {\n  required(Array.isArray(release.assets), 'GitHub Release 资产格式无效');\n  required(release.assets.length === assets.length, 'GitHub Release 资产数量不符');\n  const actual = new Map();\n  for (const asset of release.assets) {\n    required(typeof asset?.name === 'string' && !actual.has(asset.name), 'GitHub Release 资产名称重复或无效');\n    actual.set(asset.name, asset);\n  }\n  for (const expected of assets) {\n    const asset = actual.get(expected.name);\n    required(asset, `GitHub Release 缺少资产：${expected.name}`);\n    required(asset.state === 'uploaded', `GitHub Release 资产未完成上传：${expected.name}`);\n    required(asset.size === expected.size, `GitHub Release 资产大小不符：${expected.name}`);\n  }\n}\n\nfunction verifyReleaseOwnership(release, input, draft) {\n  required(Number.isSafeInteger(release?.id) && release.id > 0, 'GitHub Release id 无效');\n  required(release.tag_name === input.tag, 'GitHub 版本 Tag 不符');\n  required(release.name === input.title, 'GitHub Release 标题不符');\n  required(release.draft === draft, draft ? 'GitHub Release 不是草稿' : 'GitHub Release 尚未固化');\n  required(typeof release.body === 'string' && release.body.includes(sourceMarker(input)),\n    'GitHub Release 未绑定本次成功 CI 源提交');\n}\n\nfunction verifyRelease(release, input, draft) {\n  verifyReleaseOwnership(release, input, draft);\n  verifyAssets(release, input.assets);\n}\n\n// 中文注释：草稿没有稳定的最终 Tag 查询入口，只能从含草稿的 Release 列表取得唯一数字 id。\nasync function findDraft(client, input) {\n  for (let attempt = 0; attempt < 5; attempt += 1) {\n    const matches = (await client.listReleases(input.repository))\n      .filter((value) => value?.tag_name === input.tag\n        && value?.name === input.title && value?.draft === true);\n    required(matches.length <= 1, `发现多个同名 GitHub Release：${input.tag}`);\n    if (matches.length === 1) return matches[0];\n    await client.wait();\n  }\n  return null;\n}\n\n// 中文注释：GitHub 的按 Tag Release 查询不可靠地覆盖草稿，因此每次删除版本 Tag 前，\n// 都必须重新分页枚举包含草稿的 Release 列表；任何同 Tag Release 都使删除失败关闭。\nasync function verifyTagDeletionOwnership(client, input, label) {\n  const attached = (await client.listReleases(input.repository))\n    .filter((value) => value?.tag_name === input.tag);\n  required(attached.length === 0, `${label} 已附着 GitHub Release，禁止删除`);\n  required(await versionTagCommit(client, input) === input.sourceSHA,\n    `${label} 未锚定本次成功 CI 源提交，禁止删除`);\n}\n\nasync function versionTagCommit(client, input) {\n  const reference = await client.getTag(input.repository, input.tag);\n  verifyTagReference(reference, input, '正式版本 Tag');\n  if (reference.object.type === 'commit') return reference.object.sha;\n  const object = await client.getTagObject(input.repository, reference.object.sha);\n  required(object?.tag === input.tag && object?.object?.type === 'commit'\n    && SHA_PATTERN.test(String(object.object.sha || '')), '正式版本 Tag 对象无效');\n  return object.object.sha;\n}\n\nfunction verifyTagReference(reference, input, label) {\n  required(reference?.ref === `refs/tags/${input.tag}`\n    && SHA_PATTERN.test(String(reference?.object?.sha || '')),\n  `${label}不存在或无效`);\n  required(reference.object.type === 'commit' || reference.object.type === 'tag',\n    `${label}类型无效`);\n}\n\nfunction errorMessage(error) {\n  return error instanceof Error ? error.message : String(error);\n}\n\nexport async function release(input, client = createClient()) {\n  let releaseId = null;\n  let transactionStarted = false;\n  let publishAttempted = false;\n  let formalObserved = false;\n  const existing = (await client.listReleases(input.repository))\n    .filter((value) => value?.tag_name === input.tag);\n  const published = existing.filter((value) => value?.draft === false);\n  required(published.length === 0, `正式 Release 已存在，禁止覆盖：${input.tag}`);\n  const drafts = existing.filter((value) => value?.draft === true);\n  required(drafts.length <= 1, `发现多个同 Tag 草稿 Release：${input.tag}`);\n\n  // 中文注释：同版本失败重试只清理由本动作管理的精确 Tag。草稿必须携带本次 sourceSHA\n  // 隐藏标记；孤立 Tag 没有正式 Release，属于上次事务中断残留，统一删除后重新原子创建。\n  if (drafts.length === 1) {\n    verifyReleaseOwnership(drafts[0], input, true);\n    await client.deleteRelease(input.repository, drafts[0].id);\n  }\n  const staleTag = await client.getTag(input.repository, input.tag);\n  if (staleTag) {\n    // 中文注释：孤立同名 Tag 可能来自人工操作或另一事务。删除紧前必须重新确认\n    // 没有正式或草稿 Release 附着，并把轻量或注解 Tag 最终解析到准确 sourceSHA。\n    await verifyTagDeletionOwnership(client, input, '同名孤立版本 Tag');\n    try {\n      await client.deleteTag(input.repository, input.tag);\n    } catch (deleteError) {\n      // 删除请求可能已在服务端成功后丢失响应；getTag 只有准确 HTTP 404 才返回 null。\n      let remaining;\n      try {\n        remaining = await client.getTag(input.repository, input.tag);\n      } catch (checkError) {\n        throw new Error(`孤立 Tag 删除失败：${errorMessage(deleteError)}；复核失败：${errorMessage(checkError)}`);\n      }\n      required(remaining === null,\n        `孤立 Tag 删除状态未确认：${errorMessage(deleteError)}`);\n    }\n    required(await client.getTag(input.repository, input.tag) === null,\n      '孤立 Tag 删除后仍然存在');\n  }\n\n  try {\n    transactionStarted = true;\n    // 中文注释：12 个产品、端 Release 动作都从这里执行同一个原子创建动作；--target sourceSHA\n    // 让 GitHub 原子生成并精确锚定版本 Tag，隐藏标记、Release 说明、manifest 与签名保留来源证据。\n    await client.createDraft(input);\n    let draft = await findDraft(client, input);\n    required(draft, `无法取得新建草稿 Release：${input.tag}`);\n    releaseId = draft.id;\n    draft = await client.getRelease(input.repository, releaseId);\n    verifyRelease(draft, input, true);\n    // 中文注释：必须在 PATCH 调用前记录发布尝试；调用可能已在 GitHub 成功后才报错。\n    publishAttempted = true;\n    await client.publish(input.repository, releaseId, input.latest);\n\n    const result = await client.getRelease(input.repository, releaseId);\n    if (result?.draft === false) formalObserved = true;\n    verifyRelease(result, input, false);\n    const byTag = await client.getReleaseByTag(input.repository, input.tag);\n    if (byTag?.draft === false) formalObserved = true;\n    required(byTag?.id === releaseId, '版本 Tag 未关联本次 GitHub Release');\n    verifyRelease(byTag, input, false);\n    required(await versionTagCommit(client, input) === input.sourceSHA,\n      '正式版本 Tag 未锚定本次成功 CI 源提交');\n    console.log(`正式 Release 与唯一版本 Tag 已固化：${input.tag}`);\n    return result;\n  } catch (error) {\n    // 中文注释：恢复阶段先完成全部只读核对。403、503、网络错误、无效 JSON、相互冲突的\n    // 读取结果都属于未知态；一旦任一路径观察到正式 Release，该事实不可逆且禁止任何删除。\n    let rollbackRelease = null;\n    let rollbackTag = null;\n    let recoveryFailure = null;\n    try {\n      let currentRelease = null;\n      if (releaseId !== null) {\n        currentRelease = await client.getRelease(input.repository, releaseId);\n      } else {\n        const discoveredDraft = await findDraft(client, input);\n        if (discoveredDraft !== null) {\n          verifyReleaseOwnership(discoveredDraft, input, true);\n          currentRelease = await client.getRelease(input.repository, discoveredDraft.id);\n          required(currentRelease !== null, '恢复核对时草稿按 id 消失');\n          releaseId = discoveredDraft.id;\n        }\n      }\n      if (currentRelease?.draft === false) formalObserved = true;\n\n      const byTag = await client.getReleaseByTag(input.repository, input.tag);\n      if (byTag?.draft === false) formalObserved = true;\n      const formalCandidates = [currentRelease, byTag]\n        .filter((value) => value?.draft === false);\n      if (formalCandidates.length > 0) {\n        for (const candidate of formalCandidates) {\n          if (releaseId !== null) {\n            required(candidate.id === releaseId, '恢复核对读到不同 id 的正式 Release');\n          }\n          verifyRelease(candidate, input, false);\n        }\n        required(byTag?.draft === false, '正式 Release 已形成但 Tag 查询尚未关联');\n        if (releaseId !== null) {\n          required(byTag.id === releaseId, '版本 Tag 未关联本次 GitHub Release');\n        }\n        required(await versionTagCommit(client, input) === input.sourceSHA,\n          '正式版本 Tag 未锚定本次成功 CI 源提交');\n        console.log(`正式 Release 已核对恢复：${input.tag}`);\n        return byTag;\n      }\n\n      required(!formalObserved, '已经观察到正式 Release，禁止回滚');\n      // getReleaseByTag 只有在 gh 从最终 HTTP 状态行读到准确 404 时才会返回 null。\n      required(byTag === null, 'Tag 查询返回了非正式的异常 Release');\n      if (currentRelease !== null) {\n        verifyReleaseOwnership(currentRelease, input, true);\n        if (releaseId !== null) {\n          required(currentRelease.id === releaseId, '恢复核对读到不同 id 的草稿 Release');\n        }\n        rollbackRelease = currentRelease;\n      }\n      const tag = await client.getTag(input.repository, input.tag);\n      if (tag !== null) verifyTagReference(tag, input, '待回滚 Tag');\n      rollbackTag = tag;\n    } catch (candidateError) {\n      recoveryFailure = candidateError;\n    }\n\n    if (recoveryFailure !== null || formalObserved) {\n      const phase = publishAttempted ? 'PATCH 后' : '发布前';\n      const detail = recoveryFailure === null\n        ? '已经观察到正式 Release'\n        : errorMessage(recoveryFailure);\n      throw new Error(`${errorMessage(error)}；${phase}恢复核对失败，远端状态已保留：${detail}`);\n    }\n\n    const cleanupErrors = [];\n    let releaseRemovalConfirmed = rollbackRelease === null;\n    if (transactionStarted) {\n      if (rollbackRelease !== null) {\n        try {\n          await client.deleteRelease(input.repository, rollbackRelease.id);\n          releaseRemovalConfirmed = true;\n        } catch (cleanupError) {\n          // 删除调用同样可能服务端成功而本机响应中断；只有按 id 精确 404 才确认已删除。\n          try {\n            const remaining = await client.getRelease(input.repository, rollbackRelease.id);\n            if (remaining === null) {\n              releaseRemovalConfirmed = true;\n            } else {\n              if (remaining.draft === false) formalObserved = true;\n              cleanupErrors.push(`草稿回滚状态未确认：${errorMessage(cleanupError)}`);\n            }\n          } catch (checkError) {\n            cleanupErrors.push(\n              `草稿回滚失败：${errorMessage(cleanupError)}；复核失败：${errorMessage(checkError)}`,\n            );\n          }\n        }\n      }\n\n      if (releaseRemovalConfirmed && !formalObserved && rollbackTag !== null) {\n        let tagDeletionVerified = false;\n        try {\n          await verifyTagDeletionOwnership(client, input, '待回滚版本 Tag');\n          tagDeletionVerified = true;\n        } catch (verificationError) {\n          cleanupErrors.push(\n            `Tag 回滚前归属核验失败：${errorMessage(verificationError)}`,\n          );\n        }\n        if (tagDeletionVerified) {\n          try {\n            await client.deleteTag(input.repository, input.tag);\n          } catch (cleanupError) {\n            try {\n              const remaining = await client.getTag(input.repository, input.tag);\n              if (remaining !== null) {\n                cleanupErrors.push(`Tag 回滚状态未确认：${errorMessage(cleanupError)}`);\n              }\n            } catch (checkError) {\n              cleanupErrors.push(\n                `Tag 回滚失败：${errorMessage(cleanupError)}；复核失败：${errorMessage(checkError)}`,\n              );\n            }\n          }\n        }\n      } else if (!releaseRemovalConfirmed && rollbackTag !== null) {\n        cleanupErrors.push('草稿删除未确认，已保留 Tag');\n      }\n    }\n    const suffix = cleanupErrors.length > 0 ? `；${cleanupErrors.join('；')}` : '';\n    throw new Error(`${errorMessage(error)}${suffix}`);\n  }\n}\n\nexport function parseArgs(argv, environment = process.env) {\n  const values = new Map();\n  const assetIndex = argv.indexOf('--assets');\n  required(assetIndex >= 0 && assetIndex < argv.length - 1, '缺少 --assets');\n  const assetPaths = argv.slice(assetIndex + 1);\n  const optionArgs = argv.slice(0, assetIndex);\n  required(optionArgs.length % 2 === 0, 'Release 参数必须成对提供');\n  for (let index = 0; index < optionArgs.length; index += 2) {\n    const key = optionArgs[index];\n    required(/^--[a-z-]+$/.test(key) && !values.has(key), `Release 参数无效或重复：${key}`);\n    values.set(key, optionArgs[index + 1]);\n  }\n\n  const repository = environment.GITHUB_REPOSITORY;\n  const tag = values.get('--tag');\n  const sourceSHA = values.get('--source-sha');\n  const title = values.get('--title');\n  const notes = values.get('--notes');\n  const notesFile = values.get('--notes-file');\n  const latestValue = values.get('--latest');\n  required(REPOSITORY_PATTERN.test(repository || ''), 'GITHUB_REPOSITORY 无效');\n  required(TAG_PATTERN.test(tag || ''), '版本 Tag 无效');\n  required(SHA_PATTERN.test(sourceSHA || ''), 'Release 源提交无效');\n  required(typeof title === 'string' && title.trim() === title && title.length > 0, 'Release 标题无效');\n  required(Boolean(notes) !== Boolean(notesFile), '必须且只能提供 --notes 或 --notes-file');\n  required(latestValue === 'true' || latestValue === 'false', '--latest 只允许 true 或 false');\n\n  const assets = assetPaths.map((path) => {\n    const value = lstatSync(path);\n    required(value.isFile() && value.size > 0, `Release 资产不是非空普通文件：${path}`);\n    return { path, name: basename(path), size: value.size };\n  });\n  required(new Set(assets.map((asset) => asset.name)).size === assets.length, 'Release 资产文件名重复');\n  return {\n    repository,\n    tag,\n    sourceSHA,\n    title,\n    notes,\n    notesFile,\n    latest: latestValue === 'true',\n    assets,\n  };\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {\n  try {\n    await release(parseArgs(process.argv.slice(2)));\n  } catch (error) {\n    console.error(error.message);\n    process.exitCode = 1;\n  }\n}\n","node-version":"#!/usr/bin/env node\n\nimport { readFileSync, writeFileSync } from 'node:fs';\nimport { spawnSync } from 'node:child_process';\nimport { pathToFileURL } from 'node:url';\n\nconst VERSION_PATTERN = /^\\d+\\.(?:0|[1-9]\\d?)\\.(?:0|[1-9]\\d?)$/;\nconst CARGO_PATH = 'citizenchain/Cargo.toml';\nconst LOCK_PATH = 'citizenchain/Cargo.lock';\nconst TAURI_PATH = 'citizenchain/node/tauri.conf.json';\n\nfunction required(condition, message) {\n  if (!condition) throw new Error(message);\n}\n\nexport function applyVersion(version) {\n  required(VERSION_PATTERN.test(version), '公民链节点候选版本无效');\n  const tauri = JSON.parse(readFileSync(TAURI_PATH, 'utf8'));\n  tauri.version = version;\n  writeFileSync(TAURI_PATH, `${JSON.stringify(tauri, null, 2)}\\n`);\n\n  let cargo = readFileSync(CARGO_PATH, 'utf8');\n  const pattern = /(\\[workspace\\.package\\][\\s\\S]*?\\nversion\\s*=\\s*\")[^\"]+(\"\\s*)/;\n  required(pattern.test(cargo), 'CitizenChain workspace.package 版本真源无效');\n  cargo = cargo.replace(pattern, `$1${version}$2`);\n  writeFileSync(CARGO_PATH, cargo);\n}\n\nfunction packageBlocks(text) {\n  // 中文注释：Windows runner 会把检出文件转换为 CRLF，而 Cargo 重写锁文件时可能恢复 LF；\n  // 先统一换行再做逐块比对，避免把完全相同的 Cargo.lock 误判为缺少 package。\n  const normalized = text.replaceAll('\\r\\n', '\\n');\n  const marker = '[[package]]\\n';\n  const first = normalized.indexOf(marker);\n  required(first >= 0, 'Cargo.lock 缺少 package');\n  const prefix = normalized.slice(0, first);\n  const blocks = normalized.slice(first).split(/(?=^\\[\\[package\\]\\]\\n)/m);\n  return { prefix, blocks };\n}\n\nfunction packageField(block, field) {\n  return new RegExp(`^${field} = \"([^\"]+)\"$`, 'm').exec(block)?.[1] ?? null;\n}\n\nexport function validateLockChange(before, after, version) {\n  const left = packageBlocks(before);\n  const right = packageBlocks(after);\n  required(left.prefix === right.prefix && left.blocks.length === right.blocks.length,\n    'Cargo.lock 发生了非 workspace 版本变化');\n  let changes = 0;\n  for (let index = 0; index < left.blocks.length; index += 1) {\n    const oldBlock = left.blocks[index];\n    const newBlock = right.blocks[index];\n    if (oldBlock === newBlock) continue;\n    const oldName = packageField(oldBlock, 'name');\n    const newName = packageField(newBlock, 'name');\n    const oldVersion = packageField(oldBlock, 'version');\n    const newVersion = packageField(newBlock, 'version');\n    required(oldName && oldName === newName && oldVersion && newVersion === version,\n      'Cargo.lock workspace 包身份或候选版本无效');\n    required(packageField(oldBlock, 'source') === null && packageField(newBlock, 'source') === null,\n      `Cargo.lock 禁止修改远端依赖：${oldName}`);\n    const normalize = (block) => block.replace(/^version = \"[^\"]+\"$/m, 'version = \"<workspace>\"');\n    required(normalize(oldBlock) === normalize(newBlock),\n      `Cargo.lock 除 workspace 版本外发生变化：${oldName}`);\n    required(oldVersion !== newVersion, `Cargo.lock 出现无效版本变化：${oldName}`);\n    changes += 1;\n  }\n  // 中文注释：CI 只验证源码版本，不推进正式版本；源码 manifest 与 Cargo.lock 已经一致时，\n  // `cargo update --workspace` 合法地不产生差异，随后 metadata --locked 仍会验证锁定一致性。\n  return changes;\n}\n\nfunction runCargo(args) {\n  const result = spawnSync('cargo', args, {\n    cwd: 'citizenchain', encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],\n  });\n  if (result.error) throw result.error;\n  if (result.status !== 0) throw new Error(String(result.stderr || result.stdout).trim());\n}\n\nexport function lockVersion(version) {\n  required(VERSION_PATTERN.test(version), '公民链节点候选版本无效');\n  const cargo = readFileSync(CARGO_PATH, 'utf8');\n  const tauri = JSON.parse(readFileSync(TAURI_PATH, 'utf8'));\n  const escapedVersion = version.replaceAll('.', '\\\\.');\n  required(new RegExp(`\\\\[workspace\\\\.package\\\\][\\\\s\\\\S]*?\\\\nversion\\\\s*=\\\\s*\"${escapedVersion}\"`).test(cargo)\n    && tauri.version === version, '锁文件同步前的节点候选版本不一致');\n  const before = readFileSync(LOCK_PATH, 'utf8');\n  // 中文注释：全新 runner 可能尚未缓存 Cargo.lock 已钉死的 Git 源，因此这里允许 Cargo\n  // 取得锁文件所需源码；紧随其后的逐块校验仍只允许本地 workspace 包版本发生变化。\n  runCargo(['update', '--workspace']);\n  const after = readFileSync(LOCK_PATH, 'utf8');\n  validateLockChange(before, after, version);\n  runCargo(['metadata', '--locked', '--offline', '--no-deps', '--format-version', '1']);\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {\n  try {\n    const [command, version] = process.argv.slice(2);\n    if (command === 'apply') applyVersion(version);\n    else if (command === 'lock') lockVersion(version);\n    else throw new Error('公民链节点版本命令无效');\n  } catch (error) {\n    console.error(error.message);\n    process.exitCode = 1;\n  }\n}\n"});
